import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { buildWhatsAppLink } from "@/lib/config";
import { listCatalogCars, listCatalogCategories } from "@/lib/services/catalog";

export default async function HomePage() {
  const [categories, cars] = await Promise.all([
    listCatalogCategories(),
    listCatalogCars(),
  ]);

  return (
    <div className="mx-auto flex w-full max-w-7xl flex-col gap-8 px-4 py-6 sm:px-6 lg:px-10">
      <section className="space-y-5 rounded-2xl border border-primary/20 bg-gradient-to-br from-primary/5 via-background to-background p-5 sm:p-8">
        <Badge variant="outline" className="w-fit uppercase tracking-wider">
          Chinalending
        </Badge>
        <div className="space-y-3">
          <h1 className="text-3xl font-semibold leading-tight sm:text-4xl">
            Chinese auto parts catalog with VIN search
          </h1>
          <p className="text-sm text-muted-foreground sm:text-base">
            10,000+ parts for Chery, Geely, Haval and more. Delivery across Kazakhstan.
          </p>
        </div>
        <div className="flex flex-col gap-2 sm:flex-row">
          <Button asChild size="lg" className="sm:min-w-48">
            <Link href="/catalog">Open Catalog</Link>
          </Button>
          <Button asChild size="lg" variant="outline" className="sm:min-w-48">
            <a
              href={buildWhatsAppLink("Hello. I need help selecting parts.")}
              target="_blank"
              rel="noreferrer"
            >
              Write in WhatsApp
            </a>
          </Button>
        </div>
      </section>

      <section className="grid gap-4 sm:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">VIN search</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3 text-sm text-muted-foreground">
            <p>Enter VIN, detect compatible car model, then view matching parts.</p>
            <Button asChild variant="outline" size="sm">
              <Link href="/vin-search">Open VIN search</Link>
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-lg">How ordering works</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2 text-sm text-muted-foreground">
            <p>1. Find a part by OEM or model</p>
            <p>2. Add parts to cart</p>
            <p>3. Send request via WhatsApp</p>
          </CardContent>
        </Card>
      </section>

      <section className="space-y-3">
        <h2 className="text-xl font-semibold">Popular categories</h2>
        <div className="flex flex-wrap gap-2">
          {categories.slice(0, 8).map((category) => (
            <Link key={category.id} href={`/catalog/${category.slug}`}>
              <Badge variant="outline" className="py-1">
                {category.name}
              </Badge>
            </Link>
          ))}
        </div>
      </section>

      <section className="space-y-3">
        <h2 className="text-xl font-semibold">Popular car pages</h2>
        <div className="flex flex-wrap gap-2">
          {cars.slice(0, 8).map((car) => (
            <Link key={car.id} href={`/car/${car.slug}`}>
              <Badge variant="secondary" className="py-1">
                {car.fullName}
              </Badge>
            </Link>
          ))}
        </div>
      </section>

      <section className="rounded-xl border border-border/60 bg-card/80 p-5 text-center sm:p-7">
        <h3 className="text-lg font-semibold">Need manager support right now?</h3>
        <p className="mt-2 text-sm text-muted-foreground">
          Send your VIN and OEM numbers, we will confirm price and availability.
        </p>
        <Button asChild className="mt-4" size="lg">
          <a
            href={buildWhatsAppLink("Hello. Please check price and availability for my VIN.")}
            target="_blank"
            rel="noreferrer"
          >
            Contact in WhatsApp
          </a>
        </Button>
      </section>
    </div>
  );
}
